def longest_subseq_with_diff_one(arr, n):
    if n == 0:
        return 0

    # dp[i][0] = longest subsequence ending at i with last element being arr[i]
    # dp[i][1] = longest subsequence ending at i with last element being arr[i] + 1
    # Actually, let's think differently.

    # We want the longest subsequence where adjacent elements differ by exactly 1.
    # This means the subsequence can go up or down by 1 at each step.

    # Let's use DP: dp[i] = length of longest valid subsequence ending at index i.
    # For each i, we look at all j < i where abs(arr[i] - arr[j]) == 1, and dp[i] = max(dp[i], dp[j] + 1)
    # Base case: dp[i] = 1 for all i.

    dp = [1] * n
    for i in range(n):
        for j in range(i):
            if abs(arr[i] - arr[j]) == 1:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)
