def solution(a, b, n):
    from math import gcd

    g = gcd(a, b)
    if n % g != 0:
        return 'No solution'

    # Use extended Euclidean algorithm to find one solution
    def extended_gcd(a, b):
        if b == 0:
            return (a, 1, 0)
        g, x1, y1 = extended_gcd(b, a % b)
        return (g, y1, x1 - (a // b) * y1)

    g, x0, y0 = extended_gcd(a, b)
    # Scale to get solution for ax + by = n
    x = x0 * (n // g)
    y = y0 * (n // g)

    return ('x = ', x, ', y = ', y)
