import sys
from itertools import combinations

def can_place(tiles, H, W):
    """
    Check if we can place a subset of tiles to exactly cover H x W grid.
    tiles is a list of (a, b) where each tile can be placed as a x b or b x a.
    """
    # We need to check all subsets of tiles
    n = len(tiles)
    for r in range(1, n + 1):
        for subset in combinations(range(n), r):
            if can_cover(subset, tiles, H, W):
                return True
    return False

def can_cover(indices, tiles, H, W):
    """
    Check if the tiles at given indices can cover H x W grid exactly.
    Each tile can be rotated (a,b) or (b,a).
    We use backtracking to try to place tiles.
    """
    # Get the dimensions of each tile in the subset
    tile_dims = []
    for idx in indices:
        a, b = tiles[idx]
        tile_dims.append((a, b))

    # Total area must match
    total_area = sum(a * b for a, b in tile_dims)
    if total_area != H * W:
        return False

    # Try all possible orientations for each tile
    # For each tile, we have two choices: (a, b) or (b, a)
    # But if a == b, only one choice
    orientations = []
    for a, b in tile_dims:
        if a == b:
            orientations.append([(a, b)])
        else:
            orientations.append([(a, b), (b, a)])

    # Backtracking: try to place tiles one by one
    # We'll use a grid representation
    grid = [[0] * W for _ in range(H)]

    def backtrack(pos):
        if pos == len(tile_dims):
            # Check if all cells are covered
            for i in range(H):
                for j in range(W):
                    if grid[i][j] == 0:
                        return False
            return True

        # Find the first empty cell
        start_i, start_j = -1, -1
        for i in range(H):
            for j in range(W):
                if grid[i][j] == 0:
                    start_i, start_j = i, j
                    break
            if start_i != -1:
                break

        if start_i == -1:
            return True

        # Try each orientation for the current tile
        for w, h in orientations[pos]:
            # Try to place the tile with width w and height h at (start_i, start_j)
            # The tile must cover (start_i, start_j)
            # So the top-left corner can be at (start_i - di, start_j - dj)
            # where 0 <= di < h and 0 <= dj < w
            for di in range(h):
                for dj in range(w):
                    top = start_i - di
                    left = start_j - dj
                    # Check if the tile fits
                    if top < 0 or left < 0 or top + h > H or left + w > W:
                        continue
                    # Check if all cells in the tile area are empty
                    valid = True
                    cells = []
                    for i in range(top, top + h):
                        for j in range(left, left + w):
                            if grid[i][j] != 0:
                                valid = False
                                break
                            cells.append((i, j))
                        if not valid:
                            break
                    if not valid:
                        continue
                    # Place the tile
                    for i, j in cells:
                        grid[i][j] = 1
                    if backtrack(pos + 1):
                        return True
                    # Remove the tile
                    for i, j in cells:
                        grid[i][j] = 0

        return False

    return backtrack(0)

