class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # dp[i][j] = maximum length of good subsequence ending at index i with j changes
        # But we need to track the last value to know if adding next element causes a change.
        # Alternative: dp[j][last_val] = max length of subsequence with j changes and last value = last_val
        # Since nums[i] can be up to 10^9, we use a dictionary for last_val.

        # dp[j] is a dict: key = last value, value = max length of subsequence with j changes ending with that value
        dp = [dict() for _ in range(k + 1)]

        # Initialize: for each element, we can start a subsequence with 0 changes
        for i in range(n):
            val = nums[i]
            # Start new subsequence with this value, 0 changes, length 1
            if val not in dp[0] or dp[0][val] < 1:
                dp[0][val] = 1

        # Process each element
        for i in range(1, n):
            val = nums[i]
            # We'll create new_dp to avoid using updated values in the same iteration
            new_dp = [dict(d) for d in dp]

            for j in range(k + 1):
                # Option 1: append val to a subsequence that already ends with val (no new change)
                if val in dp[j]:
                    new_len = dp[j][val] + 1
                    if val not in new_dp[j] or new_dp[j][val] < new_len:
                        new_dp[j][val] = new_len

                # Option 2: append val to a subsequence that ends with a different value (new change)
                if j > 0:
                    for last_val, length in dp[j - 1].items():
                        if last_val != val:
                            new_len = length + 1
                            if val not in new_dp[j] or new_dp[j][val] < new_len:
                                new_dp[j][val] = new_len

            dp = new_dp

        # Find the maximum length across all j and all last values
        result = 0
        for j in range(k + 1):
            for length in dp[j].values():
                if length > result:
                    result = length

        return result
