    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        # dp[s] = maximum length of subsequence that sums to s
        # Initialize with -infinity, dp[0] = 0
        dp = [-float('inf')] * (target + 1)
        dp[0] = 0

        for num in nums:
