    def specialPerm(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # Sort to help with potential optimizations, but not strictly necessary
        # We'll use bitmask DP
        # dp[mask][i] = number of ways to arrange elements in mask ending with element i
        # mask is a bitmask of which elements have been used
        # i is the index of the last element used

        from functools import lru_cache

        # Precompute compatibility: can[i][j] = True if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
        can = [[False] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0:
                        can[i][j] = True

        # dp[mask][last] where mask is integer bitmask, last is index
        # Use a dictionary or 2D list
        # n <= 14, so 2^14 = 16384 masks, and 14 last positions
        # Total states: 16384 * 14 = ~229k, which is fine

        dp = [[0] * n for _ in range(1 << n)]

        # Initialize: single element permutations
        for i in range(n):
            dp[1 << i][i] = 1

        # Fill DP
        for mask in range(1 << n):
            for last in range(n):
                if dp[mask][last] == 0:
                    continue
                if not (mask & (1 << last)):
                    continue
                # Try to add next element
                for nxt in range(n):
                    if mask & (1 << nxt):
                        continue
                    if can[last][nxt]:
                        new_mask = mask | (1 << nxt)
                        dp[new_mask][nxt] = (dp[new_mask][nxt] + dp[mask][last]) % MOD

        # Sum up all dp[full_mask][i] for all i
        full_mask = (1 << n) - 1
        result = sum(dp[full_mask]) % MOD
        return result
