from math import gcd
from typing import List

class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        def first_digit(n: int) -> int:
            while n >= 10:
                n //= 10
            return n

        def last_digit(n: int) -> int:
            return n % 10

        count = 0
        n = len(nums)
        for i in range(n):
            fd = first_digit(nums[i])
            for j in range(i + 1, n):
                ld = last_digit(nums[j])
                if gcd(fd, ld) == 1:
                    count += 1
        return count
```

