class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count_beautiful(n: int) -> int:
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            length = len(digits)

            # dp[pos][prod][sum] = count of ways
            # prod can be 0..9^length, but we can cap it
            # sum can be 0..9*length
            # We use memoization with (pos, prod, sum)
            # prod: product of digits so far (if any digit is 0, prod becomes 0)
            # sum: sum of digits so far

            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dfs(pos: int, prod: int, s: int) -> int:
                if pos == length:
                    # Check if prod is divisible by s
                    if s == 0:
                        return 0
                    if prod == 0:
                        return 1  # 0 is divisible by any non-zero s
                    return 1 if prod % s == 0 else 0

                count = 0
                for d in range(10):
                    new_prod = prod * d if prod != 0 else 0
                    new_s = s + d
                    count += dfs(pos + 1, new_prod, new_s)
                return count

            return dfs(0, 1, 0)

        return count_beautiful(r) - count_beautiful(l - 1)
