class Solution:
    def countKeyChanges(self, s: str) -> int:
        if len(s) <= 1:
            return 0
        count = 0
        prev = s[0].lower()
        for i in range(1, len(s)):
            curr = s[i].lower()
            if curr != prev:
                count += 1
                prev = curr
        return count
