class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        m = len(grid)
        n = len(grid[0])

        # Generate the zigzag traversal order
        order = []
        for i in range(m):
            if i % 2 == 0:
                # Move right
                for j in range(n):
                    order.append((i, j))
            else:
                # Move left
                for j in range(n - 1, -1, -1):
                    order.append((i, j))

        # Skip every alternate cell (keep indices 0, 2, 4, ...)
        for idx in range(0, len(order), 2):
            i, j = order[idx]
            result.append(grid[i][j])

        return result
```

